{"explanation":"At 100% yearly interest, compounding $1 once gives $2. Compounding it n times gives $(1+1/n)^n$, which rises as n increases but approaches a finite limit: $e \approx 2.71828$. Even continuous compounding earns about $2.72—not an unlimited amount.","manimCode":"const title = new Text({ text: 'How much does $1 become?', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.3, 0]);

const ax = new Axes({
  xRange: [0, 50, 10], yRange: [1.9, 2.8, 0.2],
  xLength: 8, yLength: 4.7, tips: false
});
ax.moveTo([-1.4, -0.2, 0]);

const balance = n => Math.pow(1 + 1 / n, n);
const curve = ax.plot(x => balance(x), { color: BLUE, xRange: [1, 50], numSamples: 400 });
const limitLine = new Polygon({ vertices: [ax.c2p(0, Math.E), ax.c2p(50, Math.E)], color: GOLD });
limitLine.setStrokeWidth(2).setFillOpacity(0);

let n = 1;
const dot = new Dot({ point: ax.c2p(n, balance(n)), color: YELLOW });

const limitLabel = new Text({ text: 'Limit: $2.71828...', color: GOLD, fontSize: 26 });
limitLabel.moveTo([4.5, 1.65, 0]);
let countLabel = new Text({ text: '1 time per year', color: WHITE, fontSize: 25 });
countLabel.moveTo([4.5, 0.55, 0]);
let valueLabel = new Text({ text: 'Balance: $2.0000', color: YELLOW, fontSize: 26 });
valueLabel.moveTo([4.5, 0.05, 0]);

const formula = new MathTex({ latex: '\\left(1+\\frac{1}{n}\\right)^n \\longrightarrow e' });
await formula.waitForRender();
formula.moveTo([-1.4, -3.25, 0]);

await scene.play(new Write(title));
await scene.play(new AnimationGroup([new Create(ax), new Create(curve), new Create(limitLine)]));
scene.add(dot, limitLabel, countLabel, valueLabel);
await scene.play(new Write(formula));

const controls = new Controls(scene, { position: 'bottom-right', theme: 'dark', width: 260 });
controls.addSlider({ label: 'Compounds per year', min: 1, max: 50, value: 1, step: 1, onChange: val => {
  n = Math.round(val);
  dot.moveTo(ax.c2p(n, balance(n)));
  scene.remove(countLabel, valueLabel);
  countLabel = new Text({ text: `${n} times per year`, color: WHITE, fontSize: 25 });
  countLabel.moveTo([4.5, 0.55, 0]);
  valueLabel = new Text({ text: `Balance: $${balance(n).toFixed(4)}`, color: YELLOW, fontSize: 26 });
  valueLabel.moveTo([4.5, 0.05, 0]);
  scene.add(countLabel, valueLabel);
} });

await scene.wait(999999);"}

